/* --- /anzaar/css/style_1.css --- */
.content_countdown{
	clear:both;
}
.hided_element{
	visibility:hidden;
}
#title_style h1{
	padding: 0px;
	margin:0px;
}
#descrip{
	margin: 5px 0px 5px 0px;
}
.soc_icon_coneiner{
	display:inline-block;
	margin-top:2%;
	width: 100%;
}
.soc_icon_coneiner .soc_icon{
	display: inline-block;
	margin-right: 3%;
}

.soc_icon_coneiner .soc_icon img{
	width:100%;				
	max-height:82px;
}
.countdown{
	width:100%;
}
.countdown > div{
	text-align:center;
	margin-top:2%;
	float:left;
	color:#fff;
	font-size:48px;
	font-weight:bold;
}
.element_conteiner{
	text-align:center;
	display: inline-block;					
}
.time_left{
	border:none;
	display:block;
	padding-bottom: 10%;
	padding-top: 10%;
	padding-left: 25%;
	padding-right: 25%;
	font-weight:bold;
	white-space: nowrap;
}
.time_description{
	display:block;
	text-align:center;
	margin-top:1%;
	margin-bottom:1%;
	font-weight:bold;
	white-space: nowrap;
}
.element_conteiner .time_left,.element_conteiner .time_description{
	text-align: center !important;
} 
.information{
	box-sizing:border-box;
	display:inline-block;
	z-index:999999;
	width:100%;
}
#main_inform_div{
	overflow:hidden;
	box-sizing:border-box;
	display:table;
	position:relative;
	z-index:1000;
}
.aligment{
	display:table-cell;
	width: 10%;
}
	
	
	/*Countedown*/
.countdown figure ul{
	padding:0px !important;
}	
.ClassyCountdown-wrapper{
	width:100%;
}
.ClassyCountdown-wrapper > div {	
    display: inline-block;
    position: relative;
	margin-right:2%;
   
}
.ClassyCountdown-value > span{
	display:block;
}
.ClassyCountdown-value > *{
	line-height: normal !important;
	text-align: center !important;
}
.ClassyCountdown-value > *:before{
	display: none !important;
	content:"" !important;
}
.ClassyCountdown-value > *:after{
	display: none !important;
	content:"" !important;
}
.ClassyCountdown-wrapper .ClassyCountdown-value {
    width: 100%;
    position: absolute;
    top: 50%;
    text-align: center;
    left: 0;
    display: block;
}	
#countdown{
	height: auto;
}
figure, figcaption {
	display: block;
}
.transition {
    -webkit-transition: top 400ms linear;
    -moz-transition: top 400ms linear;
    -ms-transition: top 400ms linear;
    -o-transition: top 400ms linear;
    transition: top 400ms linear;
}

.timeTo {	
	line-height: 108%;
	font-weight: bold;
}
.timeTo *:before,.timeTo *:after{	
	display: none !important;
}
.timeTo figcaption{	
	position: static !important;
}

.timeTo li{	
	line-height: inherit !important;
	padding: 0px !important;
	border:0px !important;
	font-size: inherit !important;
}
.timeTo ul{	
	line-height: inherit !important;
	padding: 0px !important;
	border:0px !important;
	font-size: inherit !important;
}
.timeTo li:before{	
	content: "" !important;
}
.timeTo span {
	vertical-align: top;
}
.timeTo figure {
	display: inline-block;
	margin: 0;
	padding: 0;
}
.timeTo figcaption {
	text-align: center;
	/*font-size: 12px;*/
	line-height: 80%;
	font-weight: normal;
	color: #888;
}

.timeTo div {
	position: relative;
	display: inline-block;
	/*width: 25px;
	height: 30px;*/
	border-top: 1px solid silver;
	border-right: 1px solid silver;
	border-bottom: 1px solid silver;
	overflow: hidden;
}
.timeTo div.first {
	border-left: 1px solid silver;
}

.timeTo ul {
	list-style-type: none;
	margin: 0;
	padding: 0;
	position: absolute;
	left: 3px;
}

.timeTo ul li {
    margin: 0;
    padding: 0;
    list-style: none;
}
.animate > span:after {
		display: none;
}

@-webkit-keyframes move {
	0% {
	   background-position: 0 0;
	}
	100% {
	   background-position: 50px 50px;
	}
}
	
	
		
/*    SUBSCRIBE*/
.subscribe_input{
	display:inline-block;
	box-sizing: border-box;
}
.subscribe_input > input{
	padding-left:8px;
	padding-top: 6px;
	width:100%;
	padding-bottom: 3px;
	border:1px solid;
    font-size: 16px;
	background: transparent;
	font-style: italic;
	
}


.subscribe_input.firstname{
	margin-right:2%;	
}
.subscribe_input.firstname,.subscribe_input.lastname{
	float:left;
	margin-bottom:5px;
	width:49%;
}
.subscribe_input.email{
	width:100%;
}
.subscribe_input > input:focus{
	outline:none;
}
#user_loading_and_saving img{
	height:25px;
}
	
#user_loading_and_saving{
	margin-top:6px;
	font-weight:bold;
	text-align:center;
}




.subscribe_input > input{
	box-sizing: border-box;
}
.bar { 
	position:relative;
	display:block;
	bottom:3px;
}
.bar:before, .bar:after{
	content:'';
	height:3px; 
	width:0;
	position:absolute;
	transition:0.2s ease all; 
	-moz-transition:0.2s ease all; 
	-webkit-transition:0.2s ease all;
}
.bar:before {
	left:50%;
}
.bar:after {
	right:50%; 
}

input:focus ~ .bar:before, input:focus ~ .bar:after{
	width:50%;
}
.user_mail_options {
	display:inline-block;
	width: 100%;
}

/*Link to dashboard*/


#link_style a{
	text-decoration:none;
}


